<section class="checkout-head"><a href="/<?= e($store['slug']) ?>/cart">← Back to cart</a><span>Secure checkout</span><h1>Where should we deliver?</h1><p>Your order is saved first. WhatsApp then opens with a prepared message for you to review and send.</p></section>
<div class="checkout-layout"><form class="checkout-form" method="post" action="/<?= e($store['slug']) ?>/checkout" data-checkout-form><?= csrf_field() ?><input type="hidden" name="idempotency_token" value="<?= e($checkoutToken) ?>"><input type="hidden" name="cart" data-checkout-cart>
<div class="checkout-section"><div class="checkout-section-title"><span>01</span><div><h2>Customer information</h2><p>Use a reachable number in international format.</p></div></div><div class="checkout-fields"><label>Full name<input name="name" value="<?= e(old('name')) ?>" minlength="2" maxlength="120" autocomplete="name" required></label><label>Phone number<input name="phone" value="<?= e(old('phone')) ?>" placeholder="+96171123456" pattern="\+[1-9][0-9]{7,14}" inputmode="tel" autocomplete="tel" required></label></div></div>
<div class="checkout-section"><div class="checkout-section-title"><span>02</span><div><h2>Delivery details</h2><p>Include landmarks, floor, or any directions the store needs.</p></div></div><label>Delivery address<textarea name="delivery_address" rows="4" minlength="5" maxlength="2000" autocomplete="street-address" required><?= e(old('delivery_address')) ?></textarea></label><label>Notes <em>Optional</em><textarea name="notes" rows="3" maxlength="1000" placeholder="Delivery time or other useful details"><?= e(old('notes')) ?></textarea></label></div>
<button class="place-order" type="submit" data-place-order>Save order and open WhatsApp</button><p class="checkout-legal">Opening WhatsApp does not automatically send the message. Review it there and tap send.</p></form>
